mapper.select:
select cr_jobcd 
from cmr0020 a
where a.cr_syscd=#{CM_SYSCD}

	and a.cr_itemid in

		#{item}


and not exists (select 'X'
			 from cmm0044
			where cm_userid=#{CM_USERID}
			and cm_syscd = a.cr_syscd
			and cm_jobcd = a.cr_jobcd
			)

select cm_jobcd
  from cmm0044
 where cm_userid= #{CM_USERID}
   and cm_syscd = #{CM_SYSCD}
   and cm_jobcd = #{CM_JOBCD}
